"""Extended-interval gentamicin dosing support for adult inpatients."""

IDEAL_INTERVAL_HOURS = 8
EXTENDED_INTERVAL_HOURS = 12
FURTHER_EXTENDED_INTERVAL_HOURS = 24
CONSULT_PHARMACY_THRESHOLD_CRCL = 20


def cockcroft_gault_crcl(age_years, weight_kg, serum_creatinine_mg_dl, is_female):
    sex_factor = 0.85 if is_female else 1.0
    return ((140 - age_years) * weight_kg * sex_factor) / (72 * serum_creatinine_mg_dl)


def ideal_body_weight_kg(height_cm, is_female):
    height_in = height_cm / 2.54
    base = 45.5 if is_female else 50.0
    return base + 2.3 * max(height_in - 60, 0)


def dosing_weight_kg(actual_weight_kg, ideal_weight_kg):
    # Devine-style adjustment: only correct toward ideal weight once a
    # patient is well above it, otherwise dose on actual body weight.
    if actual_weight_kg > ideal_weight_kg * 1.20:
        return ideal_weight_kg + 0.4 * (actual_weight_kg - ideal_weight_kg)
    return actual_weight_kg


def _interval_for_patient(patient):
    crcl = patient["crcl_ml_min"]
    age = patient["age_years"]

    if age < CONSULT_PHARMACY_THRESHOLD_CRCL:
        return None
    if crcl < 40:
        return FURTHER_EXTENDED_INTERVAL_HOURS
    if crcl < 60:
        return EXTENDED_INTERVAL_HOURS
    return IDEAL_INTERVAL_HOURS


def gentamicin_dosing_interval(age_years, weight_kg, height_cm, serum_creatinine_mg_dl, is_female):
    """Return (dosing_weight_kg, interval_hours) for once-daily gentamicin.

    interval_hours is None when the case falls outside the standard
    nomogram and needs individualized pharmacy dosing.
    """
    crcl = cockcroft_gault_crcl(age_years, weight_kg, serum_creatinine_mg_dl, is_female)
    ibw = ideal_body_weight_kg(height_cm, is_female)
    dose_weight = dosing_weight_kg(weight_kg, ibw)

    patient = {
        "age_years": age_years,
        "weight_kg": weight_kg,
        "crcl_ml_min": crcl,
    }
    interval_hours = _interval_for_patient(patient)
    return dose_weight, interval_hours
